import{_ as o,o as i,c as a,a2 as c}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0050 — AI implementata ma inattiva e collaborazione in tempo reale spenta","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0050-ai-inattiva-e-collab-spento.md","filePath":"adr/0050-ai-inattiva-e-collab-spento.md"}'),t={name:"adr/0050-ai-inattiva-e-collab-spento.md"};function n(d,e,l,r,s,p){return i(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="adr-0050-—-ai-implementata-ma-inattiva-e-collaborazione-in-tempo-reale-spenta" tabindex="-1">ADR-0050 — AI implementata ma inattiva e collaborazione in tempo reale spenta <a class="header-anchor" href="#adr-0050-—-ai-implementata-ma-inattiva-e-collaborazione-in-tempo-reale-spenta" aria-label="Permalink to &quot;ADR-0050 — AI implementata ma inattiva e collaborazione in tempo reale spenta&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>proposta (non accettata, non recepita nello spec); implementata e inattiva fino ad A-W7</td></tr><tr><td><strong>Data</strong></td><td>2026-11-10</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.6.6 (<code>:579</code>, schema unico dei feature flag), §2.6.4 e D-04 (<code>:559</code>, collaborazione asincrona), A-05 (<code>:70</code>), V-01 (perimetro di rete), V-08/D-02 (vault privati E2EE); <a href="./0026-shell-ui-revisione.html">ADR-0026</a> (chat ACP), <a href="./0029-web-workbench.html">ADR-0029</a>/<a href="./0030-desktop-core-wasm.html">ADR-0030</a> (core WASM), <a href="./0037-registro-funzioni-e-cloud-features.html">ADR-0037</a>, <a href="./0045-parita-per-costruzione.html">ADR-0045</a>, <a href="./0049-editor-live-milkdown.html">ADR-0049</a></td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>in parte → richiede aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner: §2.6.6 (due flag nuovi, <code>ai</code> e <code>collab</code>, con un secondo cancello di build che il flag da solo non basta ad aprire) e §2.3.2 (funzione «assistente AI nell&#39;editor», oggi assente dalla matrice). Non devia da A-05/D-04 finché <code>collab</code> è spento e senza provider: accenderlo sì (§Decisione 6)</td></tr><tr><td><strong>Superfici</strong></td><td>desktop (core Go <code>internal/ai</code>, binding <code>AIAPI</code>, eventi <code>ai:chunk</code> e <code>ai:done</code>; prove: test Go «zero richieste», <code>task parity</code>, <code>task check-gen</code>) · workbench web (capability <code>aiAssistant</code> falsa, stub <code>js</code> che tiene il codice AI fuori dal core WASM, limite di 8192 kB gzip; prove sul core: test che <code>AIAPI</code> rifiuta e che la UI non compare) · console: nessuna (nessun controllo di profilo nuovo oltre ai due flag dello schema) · cloud: schema del Config Profile e copia in <code>shared/go/features/</code> (il cloud non esegue nulla)</td></tr></tbody></table><blockquote><p><strong>Nota (M25, 2026-11-20).</strong> <a href="./0065-presenza-in-tempo-reale.html">ADR-0065</a> (accettato il 2026-11-20) aggiunge la <strong>presenza</strong> (avatar e cursori degli altri utenti sullo stesso file, solo vault condivisi) con un canale WebSocket proprio. <strong>Non accende il co-editing</strong>: il seam Yjs/CRDT resta spento e la costante di build <code>collab</code> invariata; questo ADR resta in vigore.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>La richiesta del 2026-11-10 chiede, insieme all&#39;editor su Milkdown (<a href="./0049-editor-live-milkdown.html">ADR-0049</a>), due integrazioni che Crepe offre ma che il prodotto non deve ancora attivare: l&#39;<strong>AI</strong> (assistente di scrittura con diff e streaming) e la <strong>collaborazione in tempo reale</strong> (Yjs). Entrambe vanno implementate lato client, testate e <strong>inattive</strong>.</p><p>Vincoli e trappole verificati:</p><ul><li><strong>Un flag sconosciuto vale acceso.</strong> <code>Specifications.md:579</code> e il codice lo fanno per scelta (una funzione più recente della build resta disponibile): <code>Enabled</code> in <code>shared/go/features/features.go:35-46</code> restituisce <code>true</code> se il nome non è nello schema e la configurazione non lo dice; stessa regola in <code>packages/api-client/src/features.ts:10-25</code> (<code>?? true</code>). Un <code>ai</code> o un <code>collab</code> letti nel codice ma non dichiarati nello schema nascerebbero accesi.</li><li><strong>Rete.</strong> La CSP di produzione ha <code>connect-src &#39;self&#39;</code> (<code>apps/desktop/internal/app/csp_prod.go:9-16</code>, ADR-0005): il frontend non può chiamare un provider esterno. I provider pronti di Crepe (<code>@milkdown/crepe/llm-providers/*</code>) fanno la richiesta dal frontend, con la chiave nel DOM.</li><li><strong>Vault privati.</strong> Contenuto e path di un vault privato sono opachi al server (E2EE, D-02): inviare il testo a un provider esterno annullerebbe la promessa.</li><li><strong>Core WASM.</strong> Il core compilato in WebAssembly (limite 8192 kB gzip, <code>web/scripts/esbuild.mjs:328-336</code>) non deve contenere codice di rete verso terzi; il modello per tenere un servizio fuori dal WASM c&#39;è già (<code>apps/desktop/internal/app/bindings_updater_js.go</code>, tag <code>js</code>).</li><li><strong>Capability.</strong> Ogni capability deve avere un consumatore nella UI, altrimenti <code>task parity</code> la rifiuta (<code>apps/desktop/internal/app/capabilities.go:20-22</code>).</li><li><strong>Chat.</strong> Esiste già <code>features.chat</code> (default <code>false</code>, <code>api/config-profile.schema.json:26-30</code>, <code>shared/go/features/features_gen.go:17,129</code>), che ADR-0026 definisce uno slot UI disabilitato («Chat ACP», <code>shell/ChatBar.tsx</code>) senza codice di protocollo: l&#39;integrazione ACP richiede un ADR dedicato.</li><li><strong>Collaborazione.</strong> <code>plugin-collab</code> sostituisce la cronologia di ProseMirror con <code>y-prosemirror</code> e ricrea i nodi: la conservazione per identità di ADR-0049 smette di funzionare se si accende da un profilo senza provider. A-05 e D-04 escludono l&#39;editing simultaneo.</li></ul><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="_1-«inattiva»-e-«spenta»-hanno-un-significato-preciso" tabindex="-1">1. «Inattiva» e «spenta» hanno un significato preciso <a class="header-anchor" href="#_1-«inattiva»-e-«spenta»-hanno-un-significato-preciso" aria-label="Permalink to &quot;1. «Inattiva» e «spenta» hanno un significato preciso&quot;">​</a></h3><p>Codice presente e testato; nessuna UI, nessun comando visibile; <strong>nessuna richiesta di rete possibile</strong>. Nelle build rilasciate le due funzioni non sono accendibili senza una nuova release.</p><h3 id="_2-doppio-cancello-flag-del-config-profile-e-costante-di-build" tabindex="-1">2. Doppio cancello: flag del Config Profile e costante di build <a class="header-anchor" href="#_2-doppio-cancello-flag-del-config-profile-e-costante-di-build" aria-label="Permalink to &quot;2. Doppio cancello: flag del Config Profile e costante di build&quot;">​</a></h3><ul><li><strong>Flag</strong> <code>ai</code> e <code>collab</code> in <code>api/config-profile.schema.json</code>, <code>type: boolean</code>, <strong><code>default: false</code></strong>, con descrizione «Reserved». <code>task gen</code> aggiorna <code>features_gen.go</code> e <code>packages/api-client/src/gen/features.ts</code>; va allineata anche la copia dello schema in <code>shared/go/features/config-profile.schema.json</code> (il core del client ne incorpora una copia byte per byte, <code>Specifications.md:579</code>). Proprio perché un flag sconosciuto vale acceso, i due flag <strong>devono</strong> stare nello schema; un test impedisce che il default diventi <code>true</code> (<code>featureOn({}, Feature.Ai) === false</code>, idem <code>collab</code>, sul modello di <code>state/managed.test.ts</code>).</li><li><strong>Costante di build</strong> (variabile impostabile con <code>-ldflags</code>, come <code>DisabledByBuild</code> dell&#39;updater in <code>apps/desktop/internal/updater/key.go:21-23</code>, ma con polarità inversa: spenta salvo un&#39;esplicita accensione di build). Il nome e il meccanismo sono fissati in §7.</li><li>La funzione è raggiungibile solo se <strong>entrambi</strong> i cancelli sono aperti. Un profilo con <code>ai: true</code> o <code>collab: true</code> in una build rilasciata non cambia nulla.</li><li>Conseguenza dichiarata: nessuna UI di configurazione, consenso o guida per l&#39;amministratore in questa fase. La guida admin documenta i due flag come riservati (tabella delle chiavi di <code>docs/admin-guide/profili-quote-audit.md</code>, allineata allo schema).</li></ul><h3 id="_3-ai-la-rete-parte-solo-dal-core-go" tabindex="-1">3. AI: la rete parte solo dal core Go <a class="header-anchor" href="#_3-ai-la-rete-parte-solo-dal-core-go" aria-label="Permalink to &quot;3. AI: la rete parte solo dal core Go&quot;">​</a></h3><ul><li><strong>Core Go:</strong> nuovo pacchetto <code>apps/desktop/internal/ai</code> e servizio <code>AIAPI</code> (<code>Status</code>, <code>Start</code>, <code>Cancel</code>; la scrittura della chiave del provider è un metodo dedicato, solo scrittura), aggiunto all&#39;elenco unico di <code>App.Services()</code> (<code>apps/desktop/internal/app/services.go:6-29</code>). Eventi <code>ai:chunk</code> e <code>ai:done</code> dichiarati con <code>internal/events</code> e registrati in <code>events_registry.go</code>, quindi generati in <code>events.gen.ts</code>. Provider OpenAI-compatibile e Anthropic in SSE; un provider <strong>finto</strong> per i test.</li><li><strong>Rifiuti lato Go</strong>, qualunque cosa faccia la UI: <code>Start</code> restituisce errore se il flag <code>ai</code> è spento, se la costante di build è spenta, se il vault è privato (E2EE) o se manca la configurazione del provider.</li><li><strong>Segreti:</strong> la chiave del provider non torna mai al frontend. Il deposito previsto è il keychain del sistema operativo, come i refresh token (<code>apps/desktop/internal/auth/keychain_native.go</code>, <code>go-keyring</code>); la scelta va confermata in A-W6.</li><li><strong>Frontend:</strong> nessuna UI a flag spento. Il chunk lazy <code>live-ai</code> (diff, streaming) si carica solo se flag, costante di build, capability, vault non privato e <code>Status</code> lo consentono; il provider lato TS è un <code>AsyncIterable</code> che fa da ponte agli eventi Go. Una regola ESLint vieta <code>@milkdown/crepe/llm-providers/*</code>.</li><li><strong>Web:</strong> capability <code>aiAssistant</code> (nome proposto, in <code>capabilities.go</code> come le altre: desktop <code>true</code>, web <code>false</code>, con consumatore nella UI). Stub <code>bindings_ai_js.go</code> (tag <code>js</code>, modello <code>bindings_updater_js.go</code>): <code>AIAPI</code> esiste con gli stessi metodi ma ognuno rifiuta, e <code>internal/ai</code> resta fuori dal core WASM. Sul web la CSP vieta comunque origini terze; un relay dal cloud richiederebbe un ADR futuro.</li><li><strong>Registro di parità:</strong> nuova voce <code>editor.ai</code> (desktop <code>yes</code> con i binding <code>AIAPI.*</code>; workbench <code>exception</code>, capability <code>aiAssistant</code>), con prove per superficie.</li></ul><h3 id="_4-rapporto-con-adr-0026-e-features-chat" tabindex="-1">4. Rapporto con ADR-0026 e <code>features.chat</code> <a class="header-anchor" href="#_4-rapporto-con-adr-0026-e-features-chat" aria-label="Permalink to &quot;4. Rapporto con ADR-0026 e `features.chat`&quot;">​</a></h3><p><code>features.chat</code> e <code>ChatBar</code> restano com&#39;è: slot disabilitato, senza protocollo. L&#39;AI di questo ADR <strong>non riusa</strong> la chat e non la sblocca. Un&#39;eventuale chat ACP (agenti esterni, client Go, perimetro di rete V-01) resta un ADR a parte.</p><h3 id="_5-collaborazione-integrata-sul-client-spenta-senza-provider" tabindex="-1">5. Collaborazione: integrata sul client, spenta, senza provider <a class="header-anchor" href="#_5-collaborazione-integrata-sul-client-spenta-senza-provider" aria-label="Permalink to &quot;5. Collaborazione: integrata sul client, spenta, senza provider&quot;">​</a></h3><p>Chunk lazy <code>live-collab</code> (<code>plugin-collab</code>, <code>yjs</code>, <code>y-prosemirror</code>, <code>y-protocols</code>) che richiede <strong>sia</strong> il flag <code>collab</code> (e la costante di build) <strong>sia</strong> un provider registrato. Nessun provider è presente nella build. Test: un profilo con <code>collab: true</code> da solo non carica il chunk (Playwright: la richiesta del chunk non avviene), e a flag spento un test con due editor su un <code>Y.Doc</code> in memoria passa lo stesso, senza rete.</p><h3 id="_6-rapporto-con-d-04-e-a-05" tabindex="-1">6. Rapporto con D-04 e A-05 <a class="header-anchor" href="#_6-rapporto-con-d-04-e-a-05" aria-label="Permalink to &quot;6. Rapporto con D-04 e A-05&quot;">​</a></h3><p>Il sync resta quello di D-04: sync + merge, garantito per i soli <code>.md</code>, nessun editing simultaneo. Con <code>collab</code> spento e senza provider la decisione <strong>non devia</strong> da A-05. Accendere la collaborazione in tempo reale <strong>devia da A-05/D-04</strong>, richiede un provider e un server (oggi inesistenti), la gestione dell&#39;incompatibilità con la conservazione per identità dei nodi (ADR-0049 §4) e un ADR dedicato.</p><h3 id="_7-stato-dell-implementazione-a-w6-e-a-w7-2026-11-11" tabindex="-1">7. Stato dell&#39;implementazione (A-W6 e A-W7, 2026-11-11) <a class="header-anchor" href="#_7-stato-dell-implementazione-a-w6-e-a-w7-2026-11-11" aria-label="Permalink to &quot;7. Stato dell&#39;implementazione (A-W6 e A-W7, 2026-11-11)&quot;">​</a></h3><p>Le due funzioni sono implementate e <strong>inattive</strong>: nessuna build rilasciata le apre. Ciò che segue fissa i nomi e i comportamenti effettivi, e sostituisce dove serve i «da fissare in A-W6/A-W7» delle sezioni precedenti.</p><ul><li><strong>Doppio cancello, nomi definitivi.</strong> Lato Go la costante è la variabile <code>buildEnabled</code> di <code>apps/desktop/internal/ai/ai.go</code>, accesa solo con <code>-ldflags &quot;-X memobrain/apps/desktop/internal/ai.buildEnabled=on&quot;</code>; nessuno script di rilascio, Taskfile o esbuild la passa. Lato TypeScript è <code>import.meta.env.MEMOBRAIN_AI === &#39;1&#39;</code> (AI) e <code>MEMOBRAIN_COLLAB === &#39;1&#39;</code> (collaborazione), definite in <code>apps/desktop/frontend/scripts/esbuild.mjs</code> e <code>web/scripts/esbuild.mjs</code>, spente se la variabile d&#39;ambiente non c&#39;è. I flag <code>ai</code> e <code>collab</code> stanno nello schema (<code>api/config-profile.schema.json</code>, <code>default: false</code>, «Reserved»), nella sua copia in <code>shared/go/features/</code> e nei file generati (<code>features_gen.go</code>, <code>packages/api-client/src/gen/features.ts</code>); i test impediscono che il default diventi <code>true</code> (<code>shared/go/features/features_test.go</code>, <code>editor/live/ai/gate.test.ts</code>).</li><li><strong>Collaborazione: tre cancelli, più un quarto.</strong> Il chunk si carica solo se sono veri, in quest&#39;ordine, la costante di build, il flag <code>collab</code>, almeno un <strong>provider registrato</strong> (<code>editor/live/collab/providers.ts</code>; nessuno lo è) e la room. Il plugin esbuild <code>liveCollab</code> sostituisce <code>chunks/collab.ts</code> con uno stub che lancia un errore in ogni build senza la costante: Yjs, <code>y-prosemirror</code> e <code>plugin-collab</code> non finiscono in nessun file di una build rilasciata, e col motore acceso e la costante spenta la build desktop non contiene Yjs. Con la costante accesa il totale cresce di circa 107 kB (chunk <code>collab-*.js</code> da 109 kB). Dipendenze con pin esatto: <code>@milkdown/plugin-collab</code> 7.23.0, <code>yjs</code> 13.6.33, <code>y-prosemirror</code> 1.3.7, <code>y-protocols</code> 1.0.7. Un errore del collab non impedisce mai di aprire la nota. L&#39;incompatibilità con la conservazione per identità dei nodi (§6) <strong>resta aperta</strong>: provata solo una nota semplice seminata nel <code>Y.Doc</code>.</li><li><strong>Provider Go dell&#39;AI</strong> (<code>apps/desktop/internal/ai</code>). Un provider compatibile con OpenAI e uno con Anthropic, entrambi in SSE, più un provider finto per i test. La configurazione sta in <code>&lt;DataDir&gt;/ai.json</code> (provider, URL base, modello), non in un vault: un vault sincronizzato non può cambiare l&#39;URL. L&#39;URL deve essere <code>https</code>, o <code>http</code> solo sul loopback; i redirect non si seguono. La chiave sta nel keychain del sistema (servizio <code>MemoBrain Notes AI</code>) e <code>Status</code> non la restituisce mai; <code>SetKey</code> è solo scrittura ed è protetto soltanto dalla costante di build. <code>AIAPI</code> ha <code>Status</code>, <code>Start</code>, <code>Cancel</code> e <code>SetKey</code>, gli eventi sono <code>ai:chunk</code> e <code>ai:done</code>, i codici d&#39;errore <code>ai-disabled</code>, <code>ai-private-vault</code>, <code>ai-not-configured</code>, <code>ai-busy</code> e <code>ai-invalid</code>; <code>Status.reason</code> vale <code>build</code>, <code>profile</code>, <code>private-vault</code> o <code>not-configured</code> (primo cancello chiuso, in quest&#39;ordine). Il rifiuto avviene prima di qualsiasi I/O; il flag si ricontrolla a ogni chunk, quindi una richiesta non sopravvive al flag spento; dopo <code>Cancel</code> non arriva più un chunk e dopo <code>Close</code> non parte una richiesta.</li><li><strong>Vault privati: fail-closed.</strong> Il core rifiuta se il vault è collegato e <strong>non è noto come condiviso</strong> (<code>info.Linked &amp;&amp; info.Kind != &quot;shared&quot;</code>, <code>internal/app/bindings_ai.go</code>): <code>Info</code> ignora gli errori della tabella meta e <code>saveLink</code> scrive le chiavi una per una, quindi un vault può risultare collegato con tipo vuoto, e questo non prova che non sia E2EE. Un vault non collegato (solo locale) resta consentito. Test: <code>TestAIAPIRefusesBeforeAnyRequest</code>, con i casi privato, sconosciuto e «collegato senza tipo», e nessuna richiesta di rete.</li><li><strong>Filtri sui log e sui messaggi d&#39;errore.</strong> Wails v3 scrive gli argomenti di ogni chiamata a livello debug (<code>SetKey</code> compreso): <code>telemetry.UIRuntimeLogger</code> scarta tutto sotto Warn (vedi <a href="./0051-wails-v3.html">ADR-0051</a>), quindi la chiave non arriva ai log. Nei messaggi d&#39;errore dei provider la chiave si toglie <strong>prima</strong> del taglio a 500 byte (<code>quote</code> in <code>ai/http.go</code>; la lettura del corpo prende <code>500 + len(chiave)</code> byte, così una chiave a cavallo del limite si vede intera), e <code>providerError</code> usa la stessa funzione; test <code>TestKeyAcrossTheCutIsRedacted</code> (corpo HTTP ed evento di errore nello stream, con la chiave in tre posizioni attorno al byte 500).</li><li><strong>Core WebAssembly senza codice AI.</strong> <code>bindings_ai_js.go</code> (tag <code>js</code>) dà ad <code>AIAPI</code> gli stessi metodi, che rifiutano tutti con <code>ai-disabled</code>; <code>linked_test.go</code> verifica con <code>go list -deps</code> che <code>internal/ai</code> e <code>go-keyring</code> non siano nel core. Nel binario non compaiono le stringhe <code>anthropic-version</code>, <code>api.openai.com</code>, <code>MemoBrain Notes AI</code> e <code>chat/completions</code>. Dimensione misurata con i flag di <code>task wasm-core</code>: 7.209.026 byte gzip (circa 7.040 kB); il rapporto del budget di build web dà 7099 kB; limite 8192 kB.</li><li><strong>Frontend.</strong> <code>attachAi</code> e <code>attachCollab</code> sono chiamati da <code>MilkdownAdapter</code> prima di <code>create()</code> (opzioni <code>vaultId</code> e <code>collabRoom</code>; vault da <code>useAppStore</code>, path da <code>completion.notePath()</code>); un errore di una delle due non impedisce di aprire la nota. L&#39;AI ha i cancelli costante, flag, capability <code>aiAssistant</code> (<code>can(&#39;aiAssistant&#39;)</code> in <code>gate.ts</code>), vault non privato e <code>Status</code>. Il provider TS è un <code>AsyncIterable</code> che fa da ponte agli eventi Go; ESLint vieta <code>@milkdown/crepe/llm-providers*</code> con import statici e dinamici, <strong>anche nei test</strong> (selettore <code>llmProviderDynamicImport</code> in <code>eslint.config.js</code>). Con il motore acceso il chunk AI (57 kB) viene sempre emesso e mai richiesto se i cancelli sono chiusi. Le stringhe <code>errors.ai-*</code> sono in <code>i18n/{it,en}.json</code>; le etichette dell&#39;assistente restano quelle inglesi di Crepe.</li><li><strong>Prove.</strong> Go: <code>go test -race</code> su <code>internal/ai</code> e <code>internal/app</code> (con <code>MEMOBRAIN_REQUIRE_BINDINGS=1</code>), test WebAssembly di <code>internal/ai</code>, <code>internal/app</code>, <code>internal/rpc</code> e <code>internal/events</code>. TS: 26 test in <code>editor/live/ai</code> (un Crepe vero in jsdom con provider finto: stream, diff, accettazione che cambia una sola riga del file, rifiuto che lascia il file identico byte per byte, errore, cancelli chiusi), <code>ai/wiring.test.ts</code> (5 casi, con i cancelli veri), <code>collab/collab.test.ts</code>, <code>converge.test.ts</code> (due editor su un <code>Y.Doc</code> in memoria, nessun <code>fetch</code>), <code>collab/wiring.test.ts</code>. e2e: <code>live-ai.spec.ts</code> e <code>live-collab.spec.ts</code> (un profilo con <code>ai: true</code> o <code>collab: true</code> in build normale non richiede mai il chunk). Mutazioni provate: togliere un cancello (costante, flag, vault privato), il rifiuto dei redirect, la redazione della chiave o l&#39;ordine tra <code>Cancel</code> e i chunk fa fallire almeno un test.</li><li><strong>Registro di parità.</strong> <code>editor.ai</code>: desktop <code>exception</code> (motivo «inattiva (ADR-0050)») e workbench <code>exception</code>; <code>editor.collab</code>: <code>missing</code> su entrambe le superfici. <code>attachAi</code> e <code>attachCollab</code> sono collegati all&#39;editor (dietro le costanti di build <code>MEMOBRAIN_AI</code> e <code>MEMOBRAIN_COLLAB</code>; dal 2026-11-12 l&#39;editor Milkdown non ha più un interruttore, ADR-0049 A-W9) e restano irraggiungibili: il motivo e le prove delle due voci in <code>shared/parity/features.yaml</code> devono dirlo. Dal 2026-11-11 le prove elencate sono quelle di questo paragrafo: per <code>editor.ai</code> anche <code>ai/wiring.test.ts</code> e <code>live-ai.spec.ts</code>, per <code>editor.collab</code> i test di <code>collab/</code> (<code>collab.test.ts</code>, <code>converge.test.ts</code>, <code>wiring.test.ts</code>) e <code>live-collab.spec.ts</code>; <code>task parity</code> è verde.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Provider pronti di Crepe (<code>llm-providers/*</code>).</strong> Scartata: fanno <code>fetch</code> dal frontend (la chiave starebbe nel DOM), contro <code>connect-src &#39;self&#39;</code> e contro il perimetro di rete.</li><li><strong>Solo il flag del Config Profile.</strong> Scartata: un amministratore potrebbe accendere nelle build rilasciate una funzione che non ha UI di configurazione, consenso né guida; e un flag letto ma non dichiarato nello schema nasce acceso.</li><li><strong>AI sul web con un relay dal cloud.</strong> Rinviata: richiede un servizio nuovo, la gestione dei segreti lato server e la decisione su cosa il server può vedere; non è parità e non è richiesta ora.</li><li><strong>Riusare <code>features.chat</code> e <code>ChatBar</code> per l&#39;AI.</strong> Scartata: ADR-0026 le riserva all&#39;integrazione ACP; unire le due funzioni confonderebbe i perimetri.</li><li><strong>Lasciare AI e collab fuori dal codice.</strong> Scartata dall&#39;utente: vanno «implementati ma inattivi».</li><li><strong>Collab sempre caricato.</strong> Scartata: pesa sul bundle e ricrea i nodi, compromettendo la fedeltà del sorgente.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Il core desktop cresce di un pacchetto e di un servizio (<code>AIAPI</code>) che oggi nessuna UI chiama; i test «zero richieste» (<code>httptest</code> con un <code>RoundTripper</code> che registra) diventano un controllo permanente: a flag spento, o con vault privato, non parte nessuna richiesta HTTP.</li><li>Il core WASM non cambia di peso grazie allo stub <code>js</code>; va verificato che resti entro 8192 kB gzip.</li><li><code>task parity</code> e <code>task check-gen</code> devono passare con i nuovi eventi, la capability e i flag; la copia dello schema in <code>shared/go/features/</code> va tenuta allineata.</li><li>Debito: nessuna UI per accendere le funzioni; la guida utente non le descrive; quando si vorranno attivare servono un ADR (consenso, provider, dati inviati, vault privati) e una release.</li><li>Resta aperta la trappola «flag sconosciuto = acceso» per ogni flag futuro: la regola è che ogni funzione ancora non offerta si dichiara nello schema con <code>default: false</code> prima che il codice la legga.</li><li><strong>Da aggiornare quando l&#39;ADR sarà accettato:</strong> ADR-0026 (rinvio a questo ADR), <code>docs/adr/README.md</code>, guida admin (flag <code>ai</code> e <code>collab</code>), <code>shared/parity/features.yaml</code> (<code>editor.ai</code>, <code>editor.collab</code>), CHANGELOG (sezione «Compatibilità»). <code>Specifications.md</code> va aggiornato dall&#39;owner (§2.6.6 e matrice funzioni).</li></ul><h2 id="verificato-e-non" tabindex="-1">Verificato e non <a class="header-anchor" href="#verificato-e-non" aria-label="Permalink to &quot;Verificato e non&quot;">​</a></h2><p><strong>Verificato sul repository (2026-11-10, sul commit <code>bd9efc3</code>, prima dell&#39;inizio delle onde; i numeri di riga possono spostarsi):</strong> regola «flag sconosciuto = acceso» in Go e TS; <code>chat</code> con default <code>false</code> e come placeholder disabilitato (<code>shell/ChatBar.tsx</code>); CSP con <code>connect-src &#39;self&#39;</code>; esistenza dello stub <code>bindings_updater_js.go</code> e di <code>DisabledByBuild</code>; regola «ogni capability ha un consumatore»; keychain nativo con <code>go-keyring</code>; limite 8192 kB gzip del core WASM.</p><p><strong>Riprovato dallo spike A-W0 (Milkdown/Crepe 7.23.0, 2026-11-10):</strong> nei chunk di Milkdown non c&#39;è <code>eval</code> né <code>new Function</code>, e la rete in Crepe sta solo in <code>llm-providers/*</code>; i chunk lazy AI (35 kB) e collab (106 kB) rientrano nel conteggio dei bundle dell&#39;ADR-0049 (criterio 5, fallito per il bundle iniziale). <code>plugin-collab</code> non è stato provato con un provider.</p><p><strong>Dopo A-W6 e A-W7 (2026-11-11).</strong> Esistono <code>internal/ai</code>, <code>AIAPI</code> con i suoi eventi, la capability <code>aiAssistant</code>, i due flag nello schema, lo stub <code>js</code>, le costanti di build e i chunk lazy; vedi §7 per nomi, comportamenti e prove. Verificato: <code>go vet</code> nativo e per <code>GOOS=js GOARCH=wasm</code> puliti; <code>go test -race</code> e test WebAssembly delle parti toccate verdi; <code>task gen</code> idempotente e <code>task check-gen</code> verde dopo la rigenerazione; <code>task parity</code> verde (92 funzioni, 141 binding); tutte le mutazioni sui cancelli fanno fallire un test.</p><p><strong>Non verificato.</strong> <code>task ci</code> completo; l&#39;integrazione con un provider vero (Ollama o simili su loopback, annullamento dal campo di istruzioni) e una build con <code>-X …ai.buildEnabled=on</code> più <code>MEMOBRAIN_AI=1</code>; il keychain su Windows e Linux; un prompt del keychain a ogni <code>Status</code> su macOS non firmato; il chunk AI realmente caricato nel browser; la collaborazione con un provider vero. Fragilità segnalata: <code>task check-gen</code> calcola l&#39;hash dell&#39;intero <code>git diff</code> e dei file non tracciati, quindi fallisce se un&#39;altra attività modifica il repository durante l&#39;esecuzione, e <code>xargs</code> di macOS rifiuta i percorsi oltre 255 byte (le cartelle <code>apps/desktop/frontend/private/</code> e <code>web/private/</code>, residuo di una build con <code>MEMOBRAIN_DIST</code> assoluto, oggi non esistono più). <strong>Corretto in W8:</strong> <code>MEMOBRAIN_DIST</code> accetta ora anche percorsi assoluti (<code>distDir</code> in <code>packages/workbench/build/esbuild.mjs</code>, con <code>absWorkingDir</code> nelle build): un percorso assoluto è preso così com&#39;è, uno relativo parte dalla radice del pacchetto dell&#39;app, e un valore che coincide con il pacchetto o con una sua cartella madre è rifiutato, perché la build svuota la cartella di destinazione. La fragilità di <code>task check-gen</code> (hash dell&#39;intero <code>git diff</code>, <code>xargs</code> di macOS con percorsi oltre 255 byte) resta: non è toccata da W8.</p><p><strong>Da provare:</strong> che la costante di build sia impostabile da <code>scripts/release/build-desktop.sh</code> senza toccare gli altri <code>ldflags</code>; che il keychain accetti il deposito della chiave del provider su tutte e tre le piattaforme; la condizione esatta che identifica un vault «privato» nel core (stato del collegamento al cloud); che il chunk <code>live-collab</code> non venga mai richiesto con il solo flag (Playwright).</p><p><strong>Dopo A-W8 e la revisione finale della Parte A (2026-11-11).</strong></p><ul><li><strong>Verificato:</strong> <code>live-ai</code> e <code>live-collab</code> passano nella matrice e2e con il motore Milkdown acceso (313 passati, 0 falliti, 13 saltati; da A-W9 Milkdown è sempre acceso: <code>task e2e-matrix</code> 353 passati, 13 saltati, 0 falliti). Con Milkdown acceso, su una nota con emoji, immagini locali e remote, html, code, math e mermaid, e con picker emoji, slash, find e toolbar, l&#39;unica richiesta fuori dall&#39;origine è un&#39;immagine remota bloccata dalla CSP, come con CodeMirror (nessuna richiesta di AI o collab). Con i tre interruttori spenti (misura di W8, prima di A-W9) la build predefinita non conteneva codice Milkdown, ProseMirror, Yjs né il frontend AI; da A-W9 Milkdown c&#39;è sempre, mentre Yjs (<code>y-prosemirror</code>) e il frontend AI restano fuori dalla build predefinita (<code>check-dist.sh</code> cerca <code>y-prosemirror</code>); il core WebAssembly non dipende da <code>internal/ai</code>, <code>go-keyring</code> né <code>wailsapp</code>; il servizio AI si costruisce al primo uso, quindi all&#39;avvio non legge configurazione né keychain; <code>go vet</code> (nativo e <code>js/wasm</code>) e <code>go test -race</code> di <code>internal/ai</code> e dei test AI di <code>internal/app</code> sono verdi; dipendenze con pin esatto e nessun segreto. Il CDN Twemoji di <code>plugin-emoji</code> resta come stringa nel codice, ma la base è sovrascritta in locale (<code>/emoji/</code>).</li><li><strong>Rilievi aperti (bassi):</strong> (R1) nessuna guardia di rilascio faceva fallire una build con <code>MEMOBRAIN_AI</code>, <code>MEMOBRAIN_COLLAB</code> o <code>MEMOBRAIN_LIVE_ENGINE</code> (quest&#39;ultima rimossa in A-W9) impostate (né <code>scripts/build-desktop-bin.sh</code>, che eredita l&#39;ambiente, né <code>release.yml</code>): <strong>chiuso in W8</strong> con <code>scripts/release/check-editor-switches.sh</code> e <code>check-dist.sh</code> nelle build di rilascio; (R3) le prove di <code>editor.ai</code> ed <code>editor.collab</code> in <code>shared/parity/features.yaml:1281-1304</code> non sono quelle del §7: mancano <code>ai/wiring.test.ts</code> e <code>live-ai.spec.ts</code>, e per <code>editor.collab</code> nessun test di <code>collab/</code>; N3: <code>Info</code> scarta l&#39;errore della tabella meta: <strong>chiuso in W8</strong>, <code>Manager.InfoStrict</code> restituisce l&#39;errore e il predicato «vault privato» di <code>bindings_ai.go</code> risponde <code>true</code> se la lettura fallisce (<code>Info</code> non cambia).</li><li><strong>Prima di attivarle:</strong> le etichette AI di Crepe sono solo in inglese; collab e conservazione per identità dei nodi restano incompatibili; le caselle dei task di Crepe si chiamavano tutte «Task» (in W8 sono «Task: testo»).</li><li><strong>Ancora non verificato:</strong> una build con <code>MEMOBRAIN_AI=1</code> e il chunk AI caricato davvero nel browser; un provider vero; il keychain su Windows e Linux; <code>task ci</code> completo.</li></ul>',35)])])}const m=o(t,[["render",n]]);export{g as __pageData,m as default};
